f <- function(x) x^3 - 2 * x - 5

# (1) 手写二分法
bisection <- function(f, a, b, tol = 1e-8, maxiter = 1000) {
  for (i in 1:maxiter) {
    mid <- (a + b) / 2
    if (abs(f(mid)) < tol || (b - a) / 2 < tol) {
      return(list(root = mid, iter = i))
    }
    if (f(a) * f(mid) < 0) {
      b <- mid       # 根在左半区间
    } else {
      a <- mid       # 根在右半区间
    }
  }
  return(list(root = mid, iter = maxiter))
}

# 先确认 f(a) 和 f(b) 异号
f(1)   # 1 - 2 - 5 = -6 < 0
f(3)   # 27 - 6 - 5 = 16 > 0
result1 <- bisection(f, 1, 3)
cat("二分法：root =", result1$root, "，迭代次数：", result1$iter, "\n")

# (2) Brent 法（R 内置 uniroot）
result2 <- uniroot(f, c(1, 3))
cat("Brent 法：root =", result2$root, "\n")

f <- function(x) -x^2 + x + 1/4

# (1) optimize() 一维优化
result1 <- optimize(f, interval = c(-10, 10), maximum = TRUE)
cat("optimize：x =", result1$maximum, "，f(x) =", result1$objective, "\n")

# (2) Newton 法
f_prime  <- function(x) -2 * x + 1   # 一阶导
f_double <- function(x) -2           # 二阶导

newton_opt <- function(x0, tol = 1e-8, maxiter = 100) {
  x <- x0
  for (i in 1:maxiter) {
    x_new <- x - f_prime(x) / f_double(x)   # Newton 迭代
    if (abs(x_new - x) < tol) {
      return(list(x = x_new, iter = i, value = f(x_new)))
    }
    x <- x_new
  }
  return(list(x = x, iter = maxiter, value = f(x)))
}

result2 <- newton_opt(x0 = 0)   # 初始点 x0 = 0
cat("Newton：x =", result2$x, "，f(x) =", result2$value,
    "，迭代：", result2$iter, "\n")
